{
  "givens": [
    {
      "name": "Task description",
      "quote": "In the following exercises, use direct substitution to show that each limit leads to the indeterminate form 0/0. Then, evaluate the limit."
    },
    {
      "name": "Limit expression",
      "quote": "munder(lim, x→1/2)((2(x)^(2)+3x−2)/(2x−1))"
    }
  ],
  "requirements": [
    {
      "name": "Direct substitution method for limits",
      "necessity": "The learner must know how to substitute the limiting value into a rational function to test whether the numerator and denominator both approach zero, producing the 0/0 indeterminate form.",
      "search_query": "direct substitution limit rational function 0/0 indeterminate"
    },
    {
      "name": "Recognizing indeterminate form 0/0",
      "necessity": "The learner must be able to identify that both numerator and denominator evaluate to zero at x = 1/2, indicating the need for further algebraic manipulation.",
      "search_query": "indeterminate form 0/0 when evaluating limits"
    },
    {
      "name": "Algebraic simplification of rational expressions",
      "necessity": "The learner must know how to factor or otherwise simplify the numerator and denominator of a rational expression to cancel common factors and resolve the indeterminate form.",
      "search_query": "factor quadratic 2x^2+3x-2 and simplify with denominator 2x-1"
    },
    {
      "name": "Evaluating limits after cancellation",
      "necessity": "After canceling the common factor, the learner must substitute the limiting value into the simplified expression to obtain the limit value.",
      "search_query": "evaluate limit after canceling common factor rational function"
    },
    {
      "name": "Basic polynomial factoring techniques",
      "necessity": "Factoring the quadratic numerator (2x^2+3x-2) is required to reveal a factor of (2x-1) that cancels with the denominator.",
      "search_query": "factor 2x^2+3x-2"
    }
  ]
}
